export const LOGO = "data:image/png;base64,";
export const CACHET_BMI_DEFAUT = "data:image/png;base64,";

// ============ DONNÉES DE DÉMONSTRATION ============
// ⚠ LE MÊME LOGO, EN VERSION CLAIRE (demande Timo, 26/08/2026 : « le logo
// qui est posé là tout brut… on peut faire mieux ? »).
//
// Ce qu'on a découvert en analysant le fichier : le logo est DÉJÀ sans fond
// (58 % de ses pixels sont transparents). Le carré blanc du menu ne venait
// pas de lui, mais d'une ligne de l'application qui lui collait un fond.
//
// Sauf qu'en retirant simplement ce fond, le logo devenait illisible : son
// dessin est bleu foncé, le menu est bleu nuit — contraste mesuré 2,3, là
// où il en faut 3 pour lire et 4,5 pour lire confortablement.
//
// D'où cette deuxième version, recolorée en blanc, qui se pose DIRECTEMENT
// sur le menu sombre sans aucune plaque. C'est ce que font les marques :
// une version pour fond clair, une pour fond sombre. Le vert est conservé —
// sans lui le logo perdrait son signe distinctif et deviendrait une
// silhouette quelconque.
//
// ⚠ LOGO (la version en couleurs) reste utilisée partout où le fond est
// BLANC : reçus, factures, contrats, PDF. Ne pas les intervertir.
//
// ⚠ Fabriquée automatiquement à partir de LOGO. Propre à l'écran, mais ce
// n'est pas un travail de graphiste : le jour où l'infographiste de BMI
// fournit une vraie version blanche, elle remplace celle-ci ici même.
export const LOGO_CLAIR = "data:image/png;base64,";

